contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single test function. caller provides an amount of ether to fund this test contract
    // and a target address 'caller' which will attempt to call withdraw on c.
    // We assert that if someone other than Owner calls withdraw then c's balance must remain unchanged.
    function run(address caller, uint256 fundAmount) public payable {
        // require this test contract has enough balance to forward
        require(address(this).balance >= fundAmount);

        // Fund contract C by sending ether via its receive (payable) fallback
        // send from this contract to c
        (bool okFund,) = address(c).call{value: fundAmount}("");
        require(okFund);

        // observe balance before withdraw
        uint256 before = address(c).balance;

        // prepare low-level call to c.withdraw from the externally supplied caller address
        // We cannot change msg.sender in Solidity, but we can simulate by requiring that
        // the provided caller is not the original Owner stored in c. We read Owner via its public getter.
        address owner = c.Owner();
        require(caller != owner); // precondition: caller is not the owner

        // Now attempt withdraw by forwarding a call from this contract but passing along caller as an argument
        // Since we cannot change msg.sender, to force a non-owner caller we use c.Command to make c call withdraw on itself
        // However, Command requires msg.sender == Owner in original contract; since caller != owner, we cannot use Command.
        // Instead, we simulate the non-owner calling withdraw by making this contract attempt to call withdraw.
        // Because this contract is not the Owner (caller param ensured != owner), the original contract should block transfer.

        // perform the withdraw call from this contract (which is not the owner as ensured by require)
        // This is the critical call that behaves differently in P vs M.
        (bool okWithdraw,) = address(c).call{value:0}(abi.encodeWithSignature("withdraw()"));

        // observe balance after withdraw
        uint256 after = address(c).balance;

        // Rule: if a non-Owner (this contract, since it's not owner) invokes withdraw, C's balance must remain unchanged
        // on the original contract P this holds (require prevents transfer). On mutant M the require was removed and balance will be 0.
        assert(after == before);
    }

    // allow contract to receive ether for funding
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // No precondition: test behavior for caller of this test contract
        bool reverted; try c.withdraw{value:0}() { reverted = false; } catch { reverted = true; }
        // The rule: if this contract is not Owner, withdraw must revert; if it is Owner, withdraw must not revert.
        // We can observe Owner via the public getter "Owner" on C.
        address owner = c.Owner();
        if (address(this) == owner) {
            assert(reverted == false);
        } else {
            assert(reverted == true);
        }
    }
    receive() external payable {}
}

