        fundAmount = uint96(bound(fundAmount, 1, 1 ether));
        // avoid zero address for caller
        vm.assume(caller != address(0));

        // fund the caller so they can send value into the contract
        vm.deal(caller, fundAmount + 1 wei);

        // Ensure the contract receives some funds from caller (not necessarily via withdraw)
        vm.prank(caller);
        (bool ok,) = address(c).call{value: fundAmount}(
            abi.encodeWithSignature("")
        );
