pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: ownerBalance and sendAmount; ownerAddress is derived by deploying a helper that can reject
    function testFuzz_property(uint256 sendAmount, uint256 ownerInitialBalance) public {
        // keep amounts in reasonable bounds
        sendAmount = bound(sendAmount, 0, 1 ether);
        ownerInitialBalance = bound(ownerInitialBalance, 0, 10 ether);

        // deploy a helper that will REJECT receiving ether to model a failing recipient
        Rejector ownerRejector = new Rejector();
        address ownerAddr = address(ownerRejector);

        // fund the test EOA that will call withdraw when acting as Owner
        vm.deal(address(this), 10 ether);

        // make the deployed C's Owner be this test by default (C constructor sets Owner = msg.sender)
        // but contract C sets Owner = msg.sender at deployment; we deployed C from this contract, so this contract is Owner
        // We need Owner to be the Rejector for the scenario where transfer would revert in recipient.
        // To model the real scenario, we transfer ownership by performing a Command to set Owner? The contract has no setter.
        // Instead, we simulate the Owner calling withdraw by forwarding from the Rejector via a helper that can call withdraw.

        // First fund the contract c with sendAmount from some account
        address funder = address(0xBEEF);
        vm.deal(funder, sendAmount);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: sendAmount}("");
        require(sent, "funding failed");

        // Now we need the Owner to be the Owner stored in c. c.Owner was set to msg.sender at deployment (this contract)
        // So to have the Owner be the Rejector, we must deploy c with Owner = Rejector. But test must use new C() in setUp().
        // Workaround: have this contract (current Owner) transfer the contract's balance to the Rejector by calling Command
        // But the difference is specifically about withdraw behavior when Owner calls it. The property can be observed by
        // having the real Owner (this contract) call withdraw while the recipient (payable(Owner))'s fallback may revert.
        // We can simulate that by making the Owner be a small forwarder whose call to rejector will fail. We'll deploy a Forwarder
        // that is the Owner in c and whose receive tries to forward to Rejector and thus fails.

        // Deploy a Forwarder that will act as Owner and forward any incoming funds to the Rejector and revert on receive
        Forwarder ownerForwarder = new Forwarder(ownerRejector);

        // Now we need c's Owner to be ownerForwarder. But c was deployed with Owner = address(this).
        // We cannot redeploy c (setUp requires new C()) and must keep shape. Instead, we can exploit c.Command: it requires msg.sender==Owner
        // and will call adr.call{value: msg.value}(data). We can use Command to make the contract's balance moved to ownerForwarder
        // but that does not change Owner. The target property concerns withdraw after Owner calls it. The only way for Owner to be ownerForwarder
        // is to have ownerForwarder be the same as this contract (impossible) or to have this contract call withdraw and have its payable fallback forward to Rejector and revert.
        // So we implement this contract's receive to attempt forwarding to Rejector and force a revert when withdraw uses transfer (reference) vs unchecked call (mutant).

        // To let withdraw send to Owner (this contract), we set up this contract's fallback to revert when receiving more than 0 (so transfer will revert).
        // However, this test contract is the Owner of c, as set at deployment, so we are fine: this contract is Owner.
        // We simulate a rejecting Owner by making a new RejectingOwner contract and making calls as that contract via vm.prank.
        // But vm.prank cannot change msg.sender to a contract that has code unless that contract exists; so we can deploy RejectingOwner and have it call c.withdraw.

        RejectingOwner rejOwner = new RejectingOwner(ownerRejector);

        // fund the RejectingOwner so it can be msg.sender
        vm.deal(address(rejOwner), ownerInitialBalance);

        // Now we need c's Owner to equal address(rejOwner). But c.Owner is address(this). We cannot change it.
        // So instead, we will test the invariant from perspective of current Owner (this contract). We'll have this contract act as Owner
        // and its receive will forward to Rejector and revert to model a failing recipient. To do that, we deploy a helper that will call c.withdraw
        // with msg.sender = this contract, but using a low-level call that makes the destination be a contract whose fallback fails.
        // Given constraints, simpler approach: the distinguishing behavior is when the recipient (Owner) rejects funds. Since c.Owner is this contract,
        // make this contract's receive revert when called with more than 0 gas limited conditions. We can do that by having this test contract call withdraw
        // directly and then its receive will revert — but receive reverting will revert the entire withdraw when reference uses transfer (which triggers revert),
        // while mutant ignores call return and won't revert, leaving funds in c. That matches difference. So implement receive() in this contract to revert.

        // Prepare to call c.withdraw from this contract (we are Owner). Ensure this contract has no special gas issues.
        // Call withdraw and catch whether it reverted. For the reference, transfer to Owner (this contract) will revert because our receive reverts,
        // so withdraw will revert and contract balance remains unchanged. For the mutant (unchecked call), withdraw will NOT revert and contract balance might remain >0.

