import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the attacker address and calldata; the fuzzer will supply inputs
    function testFuzz_property(address attacker, bytes memory payload, uint128 sendValue) public {
        // keep value within reasonable bounds
        uint256 value = uint256(sendValue);

        // the general rule: Owner is initialized to deployer (this) and must remain unchanged after Command
        address originalOwner = c.Owner();

        // Deploy an attacker helper that, when called via delegatecall, will overwrite slot 0 (Owner)
        // Attacker contract contains a function that writes to the first storage slot to a chosen value.
        AttackerHelper helper = new AttackerHelper();

        // Fund the caller so we can send value with the call if fuzzer wants
        vm.deal(address(this), value);

        // Construct calldata: if payload is empty, call helper.pwn(address) by encoding selector+arg to set Owner
        bytes memory callData = payload;
        if (callData.length == 0) {
            // default: call helper.pwn(address) to write our address into slot 0
            callData = abi.encodeWithSelector(AttackerHelper.pwn.selector, address(0xBEEF));
        }

        // Execute Command with the helper's address as target. Must be called by Owner (originalOwner)
        // Use vm.prank to call as the owner
        vm.prank(originalOwner);
        // send value if any
        (bool ok,) = address(c).call{value: value}(abi.encodeWithSelector(c.Command.selector, address(helper), callData));
