        // The single assertion: Owner must still equal the original owner
        assertTrue(c.Owner() == originalOwner);
    }
}

// Adversarial helper: when executed via delegatecall it will overwrite storage slot 0 (Owner)
contract AttackerHelper {
    // function that, when executed via delegatecall, writes supplied address into storage slot 0
    function pwn(address who) public {
        // storage slot 0 corresponds to Owner in C; write into it
        assembly {
            sstore(0, who)
        }
    }

    // fallback allows arbitrary calldata to do the same: interpret first 20 bytes as address and write
    fallback() external payable {
        // if calldata has at least 32 bytes, take it as address
        if (msg.data.length >= 32) {
            address who;
            assembly { who := calldataload(0) }
            assembly { sstore(0, who) }
        }
    }
}

